def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent behavior
    opp_def = 0
    opp_coop = 0
    my_def = 0
    for i in range(n):
        mine, opp = history[i]
        if opp == 'D':
            opp_def += 1
        else:
            opp_coop += 1
        if mine == 'D':
            my_def += 1

    # Fast classification: opponent always cooperated so far
    if opp_def == 0:
        # Against pure cooperator, cooperate mostly but exploit at the very end
        if n >= 95:
            return 'D'
        if n >= 85 and rng.random() < 0.5:
            return 'D'
        if n >= 60 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Opponent always defected so far: protect, but probe occasionally to allow recovery
    if opp_coop == 0:
        # After many mutual defections, probe cooperation to restart if opponent might switch
        if n >= 4 and rng.random() < 0.06:
            return 'C'
        return 'D'

    # Short-horizon behavior: strong immediate reciprocity
    last_me, last_opp = history[-1]

    # Detect very recent sustained defection by opponent
    if n >= 4:
        recent = history[-4:]
        recent_opp_def = 0
        recent_me_def = 0
        for a, b in recent:
            if b == 'D':
                recent_opp_def += 1
            if a == 'D':
                recent_me_def += 1
        if recent_opp_def >= 3:
            # Opponent is currently defecting hard. Retaliate.
            # But if we've also been defecting a lot, try to break the cycle once.
            if recent_me_def >= 3 and rng.random() < 0.35:
                return 'C'
            return 'D'

    # Estimate overall opponent cooperation rate
    coop_rate = opp_coop / n

    # Against primarily cooperative opponents, reciprocate cooperation and forgive isolated defections
    if coop_rate >= 0.65:
        if last_opp == 'D':
            # Forgive if this is a rare defection and we haven't been too punitive
            if opp_def <= max(2, n // 8) and rng.random() < 0.55:
                return 'C'
            return 'D'
        # Opponent cooperated last
        # Late-game exploitation against highly cooperative players
        if n >= 95:
            return 'D'
        if n >= 88 and rng.random() < 0.35:
            return 'D'
        # Small occasional probe, less likely as match progresses
        if n >= 10 and n < 70 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Against primarily defective opponents, defect but probe to find recoverable ones
    if coop_rate <= 0.35:
        if last_opp == 'C':
            # Reward a cooperative move to encourage more, unless repeated exploitation
            if my_def > opp_coop and rng.random() < 0.45:
                return 'D'
            return 'C'
        # Opponent defected last
        # Occasionally cooperate as a test/probe
        if n < 90 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Mixed/ambiguous opponent: tit-for-tat with forgiveness and mild probing
    if last_opp == 'D':
        # Retaliate, but forgive occasionally if opponent has some cooperation history
        if rng.random() < 0.18:
            return 'C'
        if last_me == 'D' and rng.random() < 0.25:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated. Cooperate, but exploit opportunistically near end.
        if n >= 95:
            return 'D'
        if n >= 80 and rng.random() < 0.25:
            return 'D'
        # If we've been defecting much more than them, restore cooperation
        if my_def > opp_def + 2:
            return 'C'
        # Light probing
        if n >= 5 and rng.random() < 0.03:
            return 'D'
        return 'C'
